    elseif kind == Kind.JSDocReadonlyTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local comment = d:nodeListAt(it:nextIf(mask, 1))
        return d.factory:NewJSDocReadonlyTag(tagName, comment), nil
    elseif kind == Kind.JSDocOverrideTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local comment = d:nodeListAt(it:nextIf(mask, 1))
        return d.factory:NewJSDocOverrideTag(tagName, comment), nil
    elseif kind == Kind.JSDocDeprecatedTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local comment = d:nodeListAt(it:nextIf(mask, 1))
        return d.factory:NewJSDocDeprecatedTag(tagName, comment), nil
    elseif kind == Kind.JSDocSeeTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local nameExpression = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocSeeTag(tagName, nameExpression, comment), nil
    elseif kind == Kind.JSDocImplementsTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local className = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocImplementsTag(tagName, className, comment), nil
    elseif kind == Kind.JSDocAugmentsTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local className = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocAugmentsTag(tagName, className, comment), nil
    elseif kind == Kind.JSDocSatisfiesTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local typeExpression = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocSatisfiesTag(tagName, typeExpression, comment), nil
    elseif kind == Kind.JSDocThrowsTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local typeExpression = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocThrowsTag(tagName, typeExpression, comment), nil
    elseif kind == Kind.JSDocThisTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local typeExpression = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocThisTag(tagName, typeExpression, comment), nil
    elseif kind == Kind.JSDocImportTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local importClause = d:nodeAt(it:nextIf(mask, 1))
        local moduleSpecifier = d:nodeAt(it:nextIf(mask, 2))
        local attributes = d:nodeAt(it:nextIf(mask, 3))
        local comment = d:nodeListAt(it:nextIf(mask, 4))
        return d.factory:NewJSDocImportTag(tagName, importClause, moduleSpecifier, attributes, comment), nil
    elseif kind == Kind.JSDocCallbackTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local typeExpression = d:nodeAt(it:nextIf(mask, 1))
        local name = d:nodeAt(it:nextIf(mask, 2))
        local comment = d:nodeListAt(it:nextIf(mask, 3))
        return d.factory:NewJSDocCallbackTag(tagName, typeExpression, name, comment), nil
    elseif kind == Kind.JSDocOverloadTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local typeExpression = d:nodeAt(it:nextIf(mask, 1))
        local comment = d:nodeListAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocOverloadTag(tagName, typeExpression, comment), nil
    elseif kind == Kind.JSDocTypedefTag then
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local typeExpression = d:nodeAt(it:nextIf(mask, 1))
        local name = d:nodeAt(it:nextIf(mask, 2))
        local comment = d:nodeListAt(it:nextIf(mask, 3))
        return d.factory:NewJSDocTypedefTag(tagName, typeExpression, name, comment), nil
    elseif kind == Kind.JSDocSignature then
        local it = encoder.newChildIter(childIndices)
        local typeParameters = d:nodeListAt(it:nextIf(mask, 0))
        local parameters = d:nodeListAt(it:nextIf(mask, 1))
        local typeNode = d:nodeAt(it:nextIf(mask, 2))
        return d.factory:NewJSDocSignature(typeParameters, parameters, typeNode), nil
    elseif kind == Kind.JSDocNameReference then
        return d.factory:NewJSDocNameReference(d:singleChild(childIndices)), nil
    elseif kind == Kind.ModuleDeclaration then
        local keyword = Kind.ModuleKeyword
        if commonData&1 ~= 0 then
            keyword = Kind.NamespaceKeyword
        end
        local it = encoder.newChildIter(childIndices)
        local modifiers = d:modifierListAt(it:nextIf(mask, 0))
        local name = d:nodeAt(it:nextIf(mask, 1))
        local body = d:nodeAt(it:nextIf(mask, 2))
        return d.factory:NewModuleDeclaration(modifiers, keyword, name, body), nil
    elseif kind == Kind.ImportEqualsDeclaration then
        local isTypeOnly = commonData&1 ~= 0
        local it = encoder.newChildIter(childIndices)
        local modifiers = d:modifierListAt(it:nextIf(mask, 0))
        local name = d:nodeAt(it:nextIf(mask, 1))
        local moduleReference = d:nodeAt(it:nextIf(mask, 2))
        return d.factory:NewImportEqualsDeclaration(modifiers, isTypeOnly, name, moduleReference), nil
    elseif kind == Kind.ExportDeclaration then
        local isTypeOnly = commonData&1 ~= 0
        local it = encoder.newChildIter(childIndices)
        local modifiers = d:modifierListAt(it:nextIf(mask, 0))
        local exportClause = d:nodeAt(it:nextIf(mask, 1))
        local moduleSpecifier = d:nodeAt(it:nextIf(mask, 2))
        local attributes = d:nodeAt(it:nextIf(mask, 3))
        return d.factory:NewExportDeclaration(modifiers, isTypeOnly, exportClause, moduleSpecifier, attributes), nil
    elseif kind == Kind.ImportType then
        local isTypeOf = commonData&1 ~= 0
        local it = encoder.newChildIter(childIndices)
        local argument = d:nodeAt(it:nextIf(mask, 0))
        local attributes = d:nodeAt(it:nextIf(mask, 1))
        local qualifier = d:nodeAt(it:nextIf(mask, 2))
        local typeArguments = d:nodeListAt(it:nextIf(mask, 3))
        return d.factory:NewImportTypeNode(isTypeOf, argument, attributes, qualifier, typeArguments), nil
    elseif kind == Kind.ImportClause then
        local phaseModifier = Kind.Unknown
        local switchValue = commonData & 3
        if switchValue == 1 then
            phaseModifier = Kind.TypeKeyword
        elseif switchValue == 2 then
            phaseModifier = Kind.DeferKeyword
        end
        local it = encoder.newChildIter(childIndices)
        local name = d:nodeAt(it:nextIf(mask, 0))
        local namedBindings = d:nodeAt(it:nextIf(mask, 1))
        return d.factory:NewImportClause(phaseModifier, name, namedBindings), nil
    elseif kind == Kind.ImportSpecifier then
        local isTypeOnly = commonData&1 ~= 0
        local it = encoder.newChildIter(childIndices)
        local propertyName = d:nodeAt(it:nextIf(mask, 0))
        local name = d:nodeAt(it:nextIf(mask, 1))
        return d.factory:NewImportSpecifier(isTypeOnly, propertyName, name), nil
    elseif kind == Kind.TypeParameter then
        local it = encoder.newChildIter(childIndices)
        local modifiers = d:modifierListAt(it:nextIf(mask, 0))
        local name = d:nodeAt(it:nextIf(mask, 1))
        local constraint = d:nodeAt(it:nextIf(mask, 2))
        local expression = d:nodeAt(it:nextIf(mask, 3))
        local defaultType = d:nodeAt(it:nextIf(mask, 4))
        return d.factory:NewTypeParameterDeclaration(modifiers, name, constraint, expression, defaultType), nil
    elseif kind == Kind.SyntheticReferenceExpression then
        local it = encoder.newChildIter(childIndices)
        local expression = d:nodeAt(it:nextIf(mask, 0))
        local thisArg = d:nodeAt(it:nextIf(mask, 1))
        return d.factory:NewSyntheticReferenceExpression(expression, thisArg), nil
    elseif kind == Kind.JSDocTypeLiteral then
        local isArrayType = commonData&1 ~= 0
        local nodes = d:allocNodeSlice(#childIndices)
        for i, ci in ipairs(childIndices) do
            encoder.sliceStore(nodes, i - 1, d.nodes[ci + 1])
        end
        return d.factory:NewJSDocTypeLiteral(nodes, isArrayType), nil
    elseif kind == Kind.JSDocParameterTag or kind == Kind.JSDocPropertyTag then
        local isBracketed = commonData&1 ~= 0
        local isNameFirst = commonData&2 ~= 0
        local it = encoder.newChildIter(childIndices)
        local tagName = d:nodeAt(it:nextIf(mask, 0))
        local name = d:nodeAt(it:nextIf(mask, 1))
        local typeExpression = d:nodeAt(it:nextIf(mask, 2))
        local comment = d:nodeListAt(it:nextIf(mask, 3))
        return d.factory:NewJSDocParameterOrPropertyTag(kind, tagName, name, isBracketed, typeExpression, isNameFirst, comment), nil
    else
        return nil, "unhandled node kind " .. ast.Kind_String(kind) .. " with " .. tostring(#childIndices) .. " children"
    end
end
